        for (int i = 2; i < number; i++) {
            fibonacci[i] = fibonacci[i - 2] + fibonacci[i - 1];
        }

        for (int i = number - 1; i >= 0; i--) {
            System.out.print(fibonacci[i] + " ");
        }

        System.out.println();
    }

    public static void printFibonacciReverseRecursive(int number) {
