def ceaser_encrypt(original):
    encrypted_text = ""
    for char in original:
        if 'a' <= char <= 'z':
            encrypted_text += chr((ord(char) - ord('a') + 3) % 26 + ord('a'))
        elif 'A' <= char <= 'Z':
            encrypted_text += chr((ord(char) - ord('A') + 3) % 26 + ord('A'))
        else:
            encrypted_text += char
    return encrypted_text

