    function filterSpecialCharacter(Game storage game) internal {
        bytes memory wordBytes = bytes(game.word);
        bytes memory filteredBytes = new bytes(wordBytes.length);

        uint256 index;
        for (uint256 i = 0; i < wordBytes.length; i++) {
            if (wordBytes[i] >= 'A' && wordBytes[i] <= 'Z' || wordBytes[i] >= 'a' && wordBytes[i] <= 'z') {
            filteredBytes[index++] = wordBytes[i];
            }
        }
            wordList.push(string(abi.encodePacked(filteredBytes)));
    }
    function getGameDetails(uint256 _gameId) public view returns (uint256, address, address, string memory, uint256, uint256, GameStatus) {
        Game storage game = games[_gameId];
        return (gameId, player1, player2, game.firstLetter, wordLength, pot, status);
    }

    //PARTIE 4
    /**
     * @notice  permet de terminer un jeu spécifié et d'attribuer la cagnotte du jeu au joueur actif gagnant
     * @dev     elle est appelée lorsque le mot est trouvé dans la fonction setWordToGuess
     * @dev     le solde du jeu au joueur activePlayer
     * @param   _gameId identifiant du jeu qui doit être terminé
     */
    function endGame(uint256 _gameId) public {
        status = GameStatus.finished;
        address activePlayerAddress = getActivePlayer(_gameId);
        address otherPlayer = address(0);

        uint256 currentPot = pot;
        pot = 0;
        gameBalances[_gameId][activePlayerAddress] += currentPot;
        emit GameEnded(_gameId, activePlayerAddress, otherPlayer);
        emit PotWon(_gameId, activePlayerAddress, currentPot);
        withdraw(currentPot);
    }

    /**
     * @notice  permet d'effectuer un dépôt pour participer à une partie
     * @dev     la fonction permet à un joueur d'effectuer un dépôt pour participer au jeu 
     * @dev     le montant du dépôt doit être égal au montant de la mise
     */
    function deposit(uint256 _gameId) external payable {
        require(msg.value > 0, "Le montant n est pas egal a la mise attendu");
        address activePlayerAddress = getActivePlayer(_gameId);
        require(msg.sender == activePlayerAddress, "Vous n etes pas le joueur actif dans ce jeu");
        gameBalances[_gameId][activePlayerAddress] += msg.value;
        pot += msg.value;

        emit BalanceDeposited(msg.sender, msg.value);
