    // add more here...
};

function validateMacAddress(macAddress) {
    var macAddressRegex48 = /^([0-9A-Fa-f]{2}[:-]){5}([0-9A-Fa-f]{2})$/;
    var macAddressRegex64 = /^([0-9A-Fa-f]{2}[:-]){7}([0-9A-Fa-f]{2}).([0-9A-Fa-f]{2})$/;

    if (macAddressRegex48.test(macAddress)) {
        return 'EUI-48';
    }

    if (macAddressRegex64.test(macAddress)) {
        return 'EUI-64';
    }

    return 'Invalid';
}

function getManufacturer(macAddress) {
    var oui = macAddress.substring(0, 8);


    if (manufacturers[oui]) {
        return manufacturers[oui];
    }

    return 'Unknown';
}

var macAddress = '00:00:5E:00:53:01';

var valid = validateMacAddress(macAddress);

if (valid === 'Invalid') {
    console.log('Invalid MAC Address');
} else {
    console.log('MAC Address is ' + valid);
    console.log('Manufacturer is: ' + getManufacturer(macAddress));
}
```

This program first checks whether the MAC address is valid, and if it is, determines whether it is EUI-48 or EUI-64. Then, it retrieves the manufacturer by looking up the first three bytes (called an 'OUI') in a predefined mapping and prints out the result. Please note, to apply this in a real-world scenario, you need a complete and up-to-date OUI-to-manufacturer mapping.

